const openInvoices = `-- name: OpenInvoices :many
SELECT i.id, i.company_id, i.number, i.status, i.customer_id, i.invoice_date, i.due_date, i.memo, i.subtotal, i.discount, i.dpp, i.other_dpp, i.vat, i.total, i.journal_entry_id, i.created_at, i.created_by, i.posted_at, i.posted_by, i.voided_at, i.voided_by, i.void_reason, i.version, coalesce(p.paid, 0)::numeric AS paid
FROM sales.invoices i
LEFT JOIN LATERAL (
  SELECT sum(a.amount) AS paid
  FROM sales.receipt_allocations a
  JOIN sales.receipts r ON r.id = a.receipt_id
  WHERE a.invoice_id = i.id AND r.status = 'posted'
) p ON true
WHERE i.company_id = $1 AND i.status = 'posted'
  AND ($2::uuid IS NULL OR i.customer_id = $2::uuid)
  AND coalesce(p.paid, 0) < i.total
ORDER BY i.due_date, i.number
`

type OpenInvoicesParams struct {
	CompanyID  uuid.UUID
	CustomerID *uuid.UUID
}

type OpenInvoicesRow struct {
	ID             uuid.UUID
	CompanyID      uuid.UUID
	Number         *string
	Status         string
	CustomerID     uuid.UUID
	InvoiceDate    civil.Date
	DueDate        civil.Date
	Memo           string
	Subtotal       money.Amount
	Discount       money.Amount
	Dpp            money.Amount
	OtherDpp       money.Amount
	Vat            money.Amount
	Total          money.Amount
	JournalEntryID *uuid.UUID
	CreatedAt      time.Time
	CreatedBy      *uuid.UUID
	PostedAt       *time.Time
	PostedBy       *uuid.UUID
	VoidedAt       *time.Time
	VoidedBy       *uuid.UUID
	VoidReason     *string
	Version        int32
	Paid           money.Amount
}

func (q *Queries) OpenInvoices(ctx context.Context, arg OpenInvoicesParams) ([]OpenInvoicesRow, error) {
	rows, err := q.db.Query(ctx, openInvoices, arg.CompanyID, arg.CustomerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OpenInvoicesRow
	for rows.Next() {
		var i OpenInvoicesRow
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.Number,
			&i.Status,
			&i.CustomerID,
			&i.InvoiceDate,
			&i.DueDate,
			&i.Memo,
			&i.Subtotal,
			&i.Discount,
			&i.Dpp,
			&i.OtherDpp,
			&i.Vat,
			&i.Total,
			&i.JournalEntryID,
			&i.CreatedAt,
			&i.CreatedBy,
			&i.PostedAt,
			&i.PostedBy,
			&i.VoidedAt,
			&i.VoidedBy,
			&i.VoidReason,
			&i.Version,
			&i.Paid,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

